@media (min-width: 800px) {

    .productGrid{
        .product{
            padding-left: 1.75rem;
            padding-right: 1.75rem;
        }
    }

    //NOFILTERS CATEGORY LAYOUT
    .page{
        .page-content.no-filters{
            .container.description{
                p{
                    font-size: 20px;
                }
                .page-heading{
                    font-size: 32px;
                    text-transform: uppercase;
                }
                .page-content-subcategories{
                    margin-top: 1.5rem;
                    display: inline-block;
                    .navList{
                        display: flex;
                        flex-wrap: wrap;
                        gap: 22px;
                        .navList-item{
                            .navList-action{
                                border: 1px solid $black;
                                border-radius: 30px;
                                padding: 6px 30px;
                                align-items: center;
                                span{
                                    font-size: 14px;
                                    white-space: nowrap;
                                    display: block;
                                    line-height: normal;
                                }
                            }
                        }
                    }
                }
            }
            .grid-bg{
                padding-top: 20px;
            }
            .sort-and-pagination{
                justify-content: end;
                #toggle-filters{
                    display: none;
                }
                .actionBar.sort-products{
                    .form-fieldset.actionBar-section{
                        .form-field{
                            border-radius: 30px;
                            border: 1px solid $black;
                            padding-right: 14px;
                            .form-label{
                                font-size: 14px;
                            }
                            .form-select.form-select--small {
                                font-size: 14px;
                            }
                        }
                    }
                }
                .pagination{
                    display: none;
                }
            }
        }
    }

    ////--------------
    .page.page--category{
        .page-content.container{
            .breadcrumbs{

            }
        }
        .main.full.grid-bg{
            .container{
                .page-sidebar{
                    padding-top: 8px;
                    width: 18%;
                    border: 0;
                    .facetedSearch-enabled{
                        .sidebar-header-mobile{
                            display: none;
                        }
                        .facetedSearch.sidebarBlock{
                            margin-top: 0;
                            padding-top: 0;
                            border-top-color: transparent;
                            .facetedSearch-refineFilters.sidebarBlock{
                                border-bottom: 1px solid $black;
                                padding-bottom: 19px;
                                .sidebarBlock-heading{
                                    font-size: 18px;
                                    text-transform: none;
                                }
                                .inlineList.inlineList--labels{
                                    .facetLabel{
                                        font-weight: 300;
                                        text-decoration: none;
                                        border-radius: 30px;
                                        border: 1px solid $black;
                                        background-color: $white;
                                        padding-top: 0.15rem;
                                        padding-bottom: 0.15rem;
                                        .icon{
                                            margin-left: 8px;
                                        }
                                    }
                                }
                                a[data-faceted-search-facet]{
                                    font-weight: bold;
                                    text-decoration: underline;
                                    font-size: 14px;
                                }
                            }
                            #subcategoryList{
                                display: none !important;
                                .accordion.accordion--navList{
                                    .sidebarBlock-heading{
                                        border-bottom: none;
                                        margin-bottom: 0;
                                        padding: 0 0 0.78rem 0;
                                        font-size: 18px;
                                        text-transform: none;
                                    }
                                    .navList{
                                        padding-bottom: 0;
                                        .navList-item{
                                            .navList-action{
                                                font-size: 14px;
                                            }
                                        }
                                    }
                                }
                            }
                            .facetedSearch-navList{
                                .accordion.accordion--navList{
                                    .accordion-block{
                                        border-top: 0;
                                        border-bottom: 1px solid $black;
                                        padding-bottom: 12px;
                                        margin-top: 14px;
                                        padding-top: 0;
                                        &:first-child {
                                            border-top: none;
                                        }
                                        .accordion-navigation.toggleLink{
                                            margin-bottom: 0 !important;
                                            .accordion-title{
                                                font-size: 18px;
                                                text-transform: none;
                                            }
                                        }
                                        .accordion-content{
                                            padding-top: 10px;
                                            .navList{
                                                .navList-item{
                                                    .navList-action.navList-action--checkbox{
                                                        font-size: 14px;
                                                        font-weight: 300;
                                                        padding-left: 1.85714rem;
                                                        padding-right: 0;
                                                        .navList-action-close{

                                                        }
                                                    }
                                                    .navList-action.navList-action--checkbox::before{
                                                        right: unset;
                                                        left: 0;
                                                    }
                                                    .navList-action.navList-action--checkbox::after{
                                                        right: unset;
                                                        left: 1px;
                                                    }
                                                }
                                            }
                                            .toggleLink{
                                                .toggleLink-text.toggleLink-text--off{
                                                    font-size: 12px;
                                                }
                                            }
                                        }
                                        #facetedSearch-content--price{
                                            .form{
                                                .form-fieldset{
                                                    .form-minMaxRow{
                                                        .form-field{
                                                            .form-input.form-input--small{
                                                                font-size: 12px;
                                                                padding: 4px;
                                                            }
                                                            .button.button--small{
                                                                font-size: 12px;
                                                            }
                                                        }
                                                    }
