                                        }
                                    }
                                }
                            }
                        }
                    }
                    .sort-and-pagination{
                        justify-content: end;
                        #toggle-filters{
                            display: none;
                        }
                        .actionBar.sort-products{
                            .form-fieldset.actionBar-section{
                                .form-field{
                                    border-radius: 30px;
                                    border: 1px solid $black;
                                    padding-right: 14px;
                                    .form-label{
                                        font-size: 14px;
                                    }
                                    .form-select.form-select--small {
                                        font-size: 14px;
                                    }
                                }
                            }
                        }
                        .pagination{
                            display: none;
                        }
                    }
                }
            }
        }
    }
