//PAGINATOR

#product-listing-container{
    .category__title-count{
        display: block;
        width: 100%;
        text-align: right;
        margin-bottom: 6px;
    }
    .pagination{
        .pagination-item{
            border-bottom: 0 !important;
            .pagination-link{
                color: $black;
                padding: 6px 10px;
            }
        }
        .pagination-item.pagination-item--previous, .pagination-item.pagination-item--next{
            .pagination-link{
                padding: 4px 5px;
            }
        }
        .pagination-item.pagination-item--current{
            background-color: $black;
            .pagination-link{
                color: $white;
                padding: 6px 10px;
                font-weight: normal;
            }
        }
    }
}

//USEFUL LINKS

.useful-links{
    h2{
        text-align: center;
        text-transform: unset;
        margin-bottom: 30px;
    }
    .links{
        display: flex;
        justify-content: center;
        gap: 20px;
        flex-wrap: wrap;
        .useful-link{
            border: 1px solid $black;
            padding: 8px 30px;
            text-align: center;
            border-radius: 24px;
            white-space: nowrap;
        }
    }
}
